const body = $node["B0 - Auth & ID Wrap"].json;
const items = body.items || [];
const tableNumber = body.table_number || null;
const orderType = body.order_type || 'dine_in';
const sessionId = body.kiosk_session_id;

// Validate each item has required fields
const validatedItems = items.map((item, idx) => {
  if (!item.product_id) throw new Error(`INVALID_ITEM: L'article ${idx + 1} n'a pas de product_id`);
  if (!item.quantity || item.quantity < 1) throw new Error(`INVALID_QTY: Quantité invalide pour ${item.name || 'article ' + (idx+1)}`);
  return {
    product_id: item.product_id,
    name: item.name || '',
    quantity: item.quantity,
    size: item.size || { name: 'Normal', price_modifier: 0 },
    extras: (item.extras || []).map(e => ({ name: e.name, price: Number(e.price) || 0 })),
    sauces: (item.sauces || []).map(s => ({ name: s.name, price: Number(s.price) || 0, is_free: !!s.is_free }))
  };
});

// Get unique product IDs to fetch
const productIds = [...new Set(validatedItems.map(i => i.product_id))];

return [{ json: {
  items: validatedItems,
  table_number: tableNumber,
  order_type: orderType,
  kiosk_session_id: sessionId,
  product_ids: productIds,
  payment_method: body.payment_method || 'cash'
}}];

const cart = $node['Validate Cart'].json;
const products = ($json.data || []).map(p => ({ id: p.id, ...(p.attributes || p) }));
const productMap = {};
products.forEach(p => { productMap[p.id] = p; });

// Diamond Grade: Kitchen Capacity Guard
const kitchenLoad = $("Get Cortex Surge").item.json.value || {};
if (Number(kitchenLoad.multiplier || 1.0) > 1.8) {
  throw new Error('KITCHEN_CONGESTED: La cuisine est saturée. Attente > 60m. Veuillez réessayer plus tard.');
}

let totalAmount = 0;
let maxPrepTime = 0;
const verifiedItems = [];
const outOfStock = [];

for (const item of cart.items) {
  const product = productMap[item.product_id];
  if (!product) throw new Error(`PRODUCT_NOT_FOUND: Produit ${item.product_id} introuvable`);

  // Stock check
  const stock = product.stock_quantity ?? Infinity;
  if (stock < item.quantity) {
    outOfStock.push({ name: product.name, requested: item.quantity, available: stock });
    continue;
  }

  // Server-side price calculation
  const serverPrice = product.price;
  const sizeModifier = item.size?.price_modifier || 0;
  const extrasTotal = (item.extras||[]).reduce((s, e) => s + (Number(e.price)||0), 0);
  const saucesTotal = (item.sauces||[]).filter(s => !s.is_free).reduce((s, sauce) => s + (Number(sauce.price)||0), 0);
  const unitPrice = serverPrice + sizeModifier + extrasTotal + saucesTotal;
  const subtotal = unitPrice * item.quantity;

  totalAmount += subtotal;
  maxPrepTime = Math.max(maxPrepTime, product.preparation_time_min || 10);

  verifiedItems.push({
    product_id: item.product_id,
    name: product.marketing_name || product.name || item.name,
    base_price: serverPrice,
    size: item.size,
    extras: item.extras,
    sauces: item.sauces,
    quantity: item.quantity,
    unit_price: unitPrice,
    subtotal
  });
}

if (outOfStock.length > 0 && verifiedItems.length === 0) {
  throw new Error('OUT_OF_STOCK: ' + outOfStock.map(o => `${o.name} (demandé: ${o.requested}, dispo: ${o.available})`).join(', '));
}

// Adjust ETA based on kitchen load
const finalETA = Math.ceil(maxPrepTime * Number(kitchenLoad.multiplier || 1.0));

return [{ json: {
  ...cart,
  verified_items: verifiedItems,
  out_of_stock: outOfStock,
  total_amount: totalAmount,
  estimated_ready_time: finalETA,
  kitchen_surge_multiplier: kitchenLoad.multiplier || 1.0,
  items_summary: verifiedItems.map(i => `${i.quantity}x ${i.name}${i.size?.name !== 'Normal' ? ` (${i.size.name})` : ''}`).join(', ')
}}];

const cart = $node['Verify Prices & Stock'].json;
const existingOrders = $json.data || [];
const hasExisting = existingOrders.length > 0;

if (hasExisting) {
  // MERGE: append new items to existing order
  const existing = existingOrders[0];
  const attr = existing.attributes || existing;
  const existingItems = attr.items_detailed || [];
  const mergedItems = [...existingItems, ...cart.verified_items];
  const newTotal = (attr.total_amount || 0) + cart.total_amount;
  const maxPrep = Math.max(attr.estimated_ready_time || 0, cart.estimated_ready_time);

  return [{ json: {
    action: 'UPDATE',
    order_id: existing.id,
    items_detailed: mergedItems,
    items_summary: mergedItems.map(i => `${i.quantity}x ${i.name}`).join(', '),
    total_amount: newTotal,
    estimated_ready_time: maxPrep,
    table_number: cart.table_number,
    order_type: cart.order_type,
    source: 'kiosk',
    kiosk_session_id: cart.kiosk_session_id,
    payment_method: cart.payment_method,
    is_merge: true,
    new_items_added: cart.verified_items
  }}];
}

// CREATE new order
return [{ json: {
  action: 'CREATE',
  items_detailed: cart.verified_items,
  items_summary: cart.items_summary,
  total_amount: cart.total_amount,
  estimated_ready_time: cart.estimated_ready_time,
  table_number: cart.table_number,
  order_type: cart.order_type,
  source: 'kiosk',
  kiosk_session_id: cart.kiosk_session_id,
  payment_method: cart.payment_method,
  is_merge: false,
  new_items_added: cart.verified_items
}}];

// No table — always create new order
const cart = $json;
return [{ json: {
  action: 'CREATE',
  items_detailed: cart.verified_items,
  items_summary: cart.items_summary,
  total_amount: cart.total_amount,
  estimated_ready_time: cart.estimated_ready_time,
  table_number: null,
  order_type: cart.order_type,
  source: 'kiosk',
  kiosk_session_id: cart.kiosk_session_id,
  payment_method: cart.payment_method,
  is_merge: false,
  new_items_added: cart.verified_items
}}];

const order = $json;
const strapiUrl = $env.STRAPI_URL || 'http://strapi:1337';
const token = $env.STRAPI_API_TOKEN;

let result;

if (order.action === 'UPDATE') {
  const res = await fetch(`${strapiUrl}/api/orders/${order.order_id}`, {
    method: 'PUT',
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ data: {
      items_detailed: order.items_detailed,
      items_summary: order.items_summary,
      total_amount: order.total_amount,
      estimated_ready_time: order.estimated_ready_time,
      kitchen_ticket_sent: false
    }})
  });
  result = await res.json();
  result.order_id = order.order_id;
} else {
  const res = await fetch(`${strapiUrl}/api/orders`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ data: {
      status: 'confirmed',
      total_amount: order.total_amount,
      items_summary: order.items_summary,
      items_detailed: order.items_detailed,
      table_number: order.table_number,
      order_type: order.order_type,
      source: 'kiosk',
      kiosk_session_id: order.kiosk_session_id,
      payment_method: order.payment_method,
      estimated_ready_time: order.estimated_ready_time,
      kitchen_ticket_sent: false
    }})
  });
  result = await res.json();
  result.order_id = result.data?.id || result.id;
}

return [{ json: {
  order_id: result.order_id,
  is_merge: order.is_merge,
  table_number: order.table_number,
  order_type: order.order_type,
  total_amount: order.total_amount,
  estimated_ready_time: order.estimated_ready_time,
  items_summary: order.items_summary,
  new_items: order.new_items_added,
  kiosk_session_id: order.kiosk_session_id
}}];

// Build kitchen ticket
const order = $json;
const items = order.new_items || [];
const timestamp = new Date().toLocaleString('fr-DZ', { timeZone: 'Africa/Algiers', hour: '2-digit', minute: '2-digit' });

let ticket = order.is_merge ? `🔄 *AJOUT TABLE ${order.table_number}*` : `🍽️ *NOUVELLE COMMANDE*`;
ticket += `\n📋 N° ${order.order_id}`;
if (order.table_number) ticket += ` | 🪑 Table ${order.table_number}`;
ticket += ` | ${order.order_type === 'takeaway' ? '🥡 Emporter' : '🍽️ Sur place'}`;
ticket += `\n⏰ ${timestamp}\n━━━━━━━━━━━━━━━━━`;

for (const item of items) {
  ticket += `\n*${item.quantity}x ${item.name}*`;
  if (item.size?.name && item.size.name !== 'Normal') ticket += ` (${item.size.name})`;
  if (item.extras?.length > 0) ticket += `\n   + ${item.extras.map(e => e.name).join(', ')}`;
  if (item.sauces?.length > 0) ticket += `\n   🫙 ${item.sauces.map(s => s.name + (s.is_free ? ' ✓' : '')).join(', ')}`;
  ticket += ` — ${item.subtotal} DA`;
}

ticket += `\n━━━━━━━━━━━━━━━━━\n💰 *TOTAL: ${order.total_amount} DA*`;
ticket += `\n⏱️ Prêt dans ~${order.estimated_ready_time} min`;

return [{ json: { ...order, kitchen_ticket: ticket } }];

// Update stock + mark ticket sent + log funnel event
const order = $node['Format Kitchen Ticket'].json;
const strapiUrl = $env.STRAPI_URL || 'http://strapi:1337';
const token = $env.STRAPI_API_TOKEN;

// Mark kitchen ticket sent
await fetch(`${strapiUrl}/api/orders/${order.order_id}`, {
  method: 'PUT',
  headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ data: { kitchen_ticket_sent: true, status: 'confirmed' } })
});

// Decrement stock for each item
for (const item of (order.new_items || [])) {
  try {
    const res = await fetch(`${strapiUrl}/api/products/${item.product_id}`, {
      method: 'GET',
      headers: { 'Authorization': `Bearer ${token}` }
    });
    const product = await res.json();
    const currentStock = (product.data?.attributes || product.data)?.stock_quantity;
    if (currentStock !== undefined && currentStock !== null) {
      await fetch(`${strapiUrl}/api/products/${item.product_id}`, {
        method: 'PUT',
        headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ data: { stock_quantity: Math.max(0, currentStock - item.quantity) } })
      });
    }
  } catch(e) { /* continue on stock update failure */ }
}

// Log funnel event
await fetch(`${strapiUrl}/api/funnel-events`, {
  method: 'POST',
  headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ data: {
    event_type: 'order_confirmed',
    channel: 'kiosk',
    session_id: order.kiosk_session_id,
    metadata_json: {
      order_id: order.order_id,
      total: order.total_amount,
      items_count: (order.new_items || []).reduce((s, i) => s + i.quantity, 0),
      table_number: order.table_number,
      is_merge: order.is_merge
    }
  }})
});

return [{ json: order }];
